// ─────────────────────────────────────────────────────────────────────────────
// 3. Cryptographic Token & Backend Defense Logic Simulation
// ─────────────────────────────────────────────────────────────────────────────
console.log("\n[3] Backend Cryptographic Verification & Replay Protection");

const testAppKey = "base64:4k8+rT2cW9xZ8Y7j6k5L4M3N2P1Q0R9S8T7U6V5W4X=";
const secretKey = testAppKey.startsWith("base64:")
  ? Buffer.from(testAppKey.slice(7), "base64").toString("binary")
  : testAppKey;

function generateSignedToken(action: string, issuedAt: number, nonce: string): string {
  const payloadData = {
    action,
    iat: issuedAt,
    nonce,
    ip: "8e85fb296855a817",
  };
  const b64 = Buffer.from(JSON.stringify(payloadData)).toString("base64url");
  const sig = crypto.createHmac("sha256", secretKey).update(b64).digest("hex");
  return `${b64}.${sig}`;
}

const mockCache = new Set<string>();

function simulateBackendValidation(
  token: string | null | undefined,
  honeypot: string | null | undefined,
  expectedAction: string,
  now: number,
  minSeconds = 2,
  maxSeconds = 900,
  requireToken = false
): { ok: boolean; error?: string } {
  // 1. Honeypot
  if (honeypot && honeypot.length > 0) {
    return { ok: false, error: "Automated form submission detected." };
  }

  // 2. Token presence
  if (!token) {
    if (requireToken) {
      return { ok: false, error: "Missing security verification token." };
    }
    return { ok: true }; // Graceful fallback
  }

  const parts = token.split(".");
  if (parts.length !== 2) {
    return { ok: false, error: "Invalid form security token format." };
  }

  const [payloadB64, clientSig] = parts;
  const expectedSig = crypto.createHmac("sha256", secretKey).update(payloadB64).digest("hex");
  if (expectedSig !== clientSig) {
    return { ok: false, error: "Invalid form security token signature." };
  }

  let decoded: any;
  try {
    decoded = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf-8"));
  } catch {
    return { ok: false, error: "Malformed form security token." };
  }

  // Action match
  if (decoded.action !== expectedAction) {
    return { ok: false, error: `Form security token was issued for '${decoded.action}', not '${expectedAction}'.` };
  }

  // Timing
  const elapsed = now - decoded.iat;
  if (elapsed < minSeconds) {
    return { ok: false, error: "Form submitted too quickly. Please take a moment and try again." };
  }

  if (elapsed > maxSeconds) {
    return { ok: false, error: "Form security token has expired. Please refresh and try again." };
  }

  // Replay
  const cacheKey = `used_form_nonce:${decoded.nonce}`;
  if (mockCache.has(cacheKey)) {
    return { ok: false, error: "This form submission token has already been used. Please refresh the page." };
  }
  mockCache.add(cacheKey);

  return { ok: true };
}

const now = Math.floor(Date.now() / 1000);

// Test 1: Legitimate human submission
const legitToken = generateSignedToken("signup", now - 4, "nonce_legit_001");
const resLegit = simulateBackendValidation(legitToken, "", "signup", now, 2);
assert(resLegit.ok, "Legitimate human submission (4s elapsed, empty honeypot) passes validation");

// Test 2: Honeypot populated by spam bot
const resHoneypot = simulateBackendValidation(legitToken, "https://spam-bot.online", "signup", now, 2);
assert(!resHoneypot.ok && resHoneypot.error?.includes("Automated form submission"), "Populated honeypot is immediately rejected with spam error");

// Test 3: Sub-second submission (< minSeconds)
const fastToken = generateSignedToken("signup", now, "nonce_fast_001");
const resFast = simulateBackendValidation(fastToken, "", "signup", now, 2);
assert(!resFast.ok && resFast.error?.includes("too quickly"), "Sub-second submission (0s elapsed) is rejected as too fast");

// Test 4: Action mismatch (order-checkout token submitted to signup)
const rfqToken = generateSignedToken("order-checkout", now - 5, "nonce_action_001");
const resMismatch = simulateBackendValidation(rfqToken, "", "signup", now, 2);
assert(!resMismatch.ok && resMismatch.error?.includes("was issued for 'order-checkout'"), "Token issued for 'order-checkout' is rejected on 'signup'");

// Test 5: Replay attack (re-submitting same token)
const resReplay = simulateBackendValidation(legitToken, "", "signup", now + 1, 2);
assert(!resReplay.ok && resReplay.error?.includes("already been used"), "Replaying previously consumed token is rejected by nonce cache");

// Test 6: Expired token (> 15 minutes)
const expiredToken = generateSignedToken("signup", now - 1000, "nonce_exp_001");
const resExpired = simulateBackendValidation(expiredToken, "", "signup", now, 2);
assert(!resExpired.ok && resExpired.error?.includes("expired"), "Token older than 15 minutes is rejected as expired");

// Test 7: Tampered signature
const tamperedToken = legitToken.slice(0, -4) + "abcd";
const resTampered = simulateBackendValidation(tamperedToken, "", "signup", now, 2);
assert(!resTampered.ok && resTampered.error?.includes("signature"), "Tampered token signature is rejected");

// Test 8: Missing token graceful fallback (when requireToken = false)
const resMissing = simulateBackendValidation(null, "", "signup", now, 2, 900, false);
assert(resMissing.ok, "Missing token falls back gracefully when requireToken = false to protect edge-case users");

// ─────────────────────────────────────────────────────────────────────────────
// 4. Effective Nginx Configuration Verification
// ─────────────────────────────────────────────────────────────────────────────
console.log("\n[4] Effective Nginx Limits & Overrides Verification");

const nginxConfPath = path.join(backendDir, "security", "nginx-virtual-host.conf");
assert(fs.existsSync(nginxConfPath), "nginx-virtual-host.conf exists in backend/security/");

const nginxConf = fs.readFileSync(nginxConfPath, "utf-8");

assert(
  nginxConf.includes("client_max_body_size 2M;") &&
  nginxConf.includes("location /api {") &&
  nginxConf.includes("client_max_body_size 2M;"),
  "Nginx config sets baseline client_max_body_size 2M on standard API locations"
);

assert(
  nginxConf.includes("location ~* ^/api/v1/orders/[^/]+/payment-proof {") &&
  nginxConf.includes("client_max_body_size 20M;") &&
  nginxConf.includes("limit_req zone=req_api_upload burst=3 nodelay;"),
  "Payment proof route has 20M upload override with req_api_upload burst 3"
);

assert(
  nginxConf.includes("location ~* ^/api/v1/rfq {") &&
  nginxConf.includes("client_max_body_size 20M;") &&
  nginxConf.includes("limit_req zone=req_api_upload burst=5 nodelay;"),
  "RFQ route has 20M upload override with req_api_upload burst 5"
);

assert(
  nginxConf.includes("location = /api/v1/upload {") &&
  nginxConf.includes("client_max_body_size 20M;") &&
  nginxConf.includes("limit_req zone=req_api_upload burst=5 nodelay;"),
  "Admin media upload route has 20M upload override with req_api_upload burst 5"
);

assert(
  nginxConf.includes('fastcgi_param HTTP_X_INTERNAL_SECRET "";'),
  "Nginx strips incoming HTTP_X_INTERNAL_SECRET from FastCGI environment"
);

console.log("\n================================================================================");
console.log(`  PHASE 2 FRONTEND ANTI-BOT E2E RESULTS: ${passed} PASSED, ${failed} FAILED`);
console.log("================================================================================");

if (failed > 0) {
  process.exit(1);
}
